consumer.subscribe(List.of("orders"), new ConsumerRebalanceListener() {

    @Override
    public void onPartitionsRevoked(Collection<TopicPartition> revoked) {
        // 빼앗기기 직전 -- 마지막 기회다
        log.info("revoked {}", revoked);
        consumer.commitSync(currentOffsets);      // 여기서 커밋한다
        flushPendingWrites();
    }

    @Override
    public void onPartitionsAssigned(Collection<TopicPartition> assigned) {
        // 새로 받았다
        log.info("assigned {}", assigned);
        // 필요하면 seek 으로 시작 위치를 정한다
    }

    @Override
    public void onPartitionsLost(Collection<TopicPartition> lost) {
        // 이미 빼앗겼다 (poll 간격 초과 등) -- 커밋해 봐야 실패한다
        log.warn("lost {} -- cleaning up without commit", lost);
        discardPending();
    }
});

